const b = (
  scene: string,
  predict: [string, string[], number],
  rule: string,
  why: string,
  onRoad: string,
  trap: string,
  tip: string,
  mission: string,
): LessonBlocks => ({ scene, predict: { prompt: predict[0], options: predict[1], correct: predict[2] }, rule, why, onRoad, trap, tip, mission })

const L = (
  id: string,
  subtopicId: string,
  title: string,
  scene: SceneKind,
  sign: SignKind | undefined,
  legalRef: string,
  blocks: LessonBlocks,
  durationSec = 240,
): Lesson => {
  const st = subtopics.find((s) => s.id === subtopicId)!
  return {
    id,
    subtopicId,
    topicId: st.topicId,
    schoolId: null,
    title,
    scene,
    sign,
    durationSec,
    blocks,
    legalRef,
    attachments: [
      { id: `${id}-a1`, kind: 'image', label: 'Sign chart (zoomable)', size: '420 KB' },
      { id: `${id}-a2`, kind: 'file', label: 'Revision sheet — Additional material', size: '1.2 MB' },
      { id: `${id}-a3`, kind: 'link', label: 'Law n° 014/2026 — official text', url: 'https://www.minijust.gov.rw' },
    ],
    status: 'published',
    version: 1,
    hasVideo: true,
    authorId: 'u-editor',
    updatedAt: '2026-09-10T09:00:00Z',
  }
}

