const q = (
  id: string,
  topicId: string,
  prompt: string,
  options: string[],
  correct: number | number[],
  explanation: string,
  opts: Partial<Pick<Question, 'sign' | 'scene' | 'lessonId' | 'difficulty' | 'type' | 'wrongWhy'>> = {},
): Question => ({
  id,
  topicId,
  prompt,
  options,
  correct: Array.isArray(correct) ? correct : [correct],
  explanation,
  schoolId: null,
  type: opts.type ?? (options.length === 2 && options[0] === 'True' ? 'truefalse' : Array.isArray(correct) ? 'multi' : 'single'),
  difficulty: opts.difficulty ?? 2,
  status: 'published',
  version: 1,
  stats: { attempts: 0, correct: 0 },
  ...opts,
})

